#include <linux/skbuff.h>
#include <linux/netlink.h>
#include <linux/err.h>

int notify_sa_flush(const struct km_event *c) {
    struct sk_buff *skb;
    struct nlmsghdr *nlh;
    int err;

    skb = alloc_skb(NLMSG_GOODSIZE, GFP_KERNEL);
    if (!skb)
        return -ENOBUFS;

    nlh = nlmsg_put(skb, 0, c->sequence, NLMSG_DONE, 0, 0);
    if (!nlh) {
        kfree_skb(skb);
        return -ENOBUFS;
    }

    nlh->nlmsg_type = c->protocol;
    nlh->nlmsg_flags |= NLM_F_MULTI;

    netlink_broadcast(skb, 0, 0, 0, GFP_KERNEL);
    return 0;
}

int handle_flush_sa_notification(const struct km_event *c)
{
    struct sk_buff *skb;
    struct sadb_msg *msg;

    skb = alloc_skb(sizeof(*msg), GFP_KERNEL);
    if (!skb)
        return -ENOBUFS;

    msg = skb_put(skb, sizeof(*msg));
    msg->sadb_msg_type = SADB_MSG_FLUSH;
    msg->sadb_msg_satype = c->proto;
    msg->sadb_msg_len = sizeof(*msg) / sizeof(uint64_t);
    msg->sadb_msg_seq = c->seq;
    msg->sadb_msg_errno = 0;

    netlink_broadcast(skb, 0, 0, NL_GROUP_USERS, GFP_KERNEL);
    return 0;
}

