#include <linux/skbuff.h>
#include <linux/errno.h>
#include <linux/netlink.h>

int handle_sa_flush_notification(const struct km_event *c)
{
    struct sk_buff *skb;
    struct nlmsghdr *nlh;
    int msg_size = NLMSG_SPACE(0); // No payload for this message

    skb = alloc_skb(msg_size, GFP_KERNEL);
    if (!skb)
        return -ENOBUFS;

    nlh = nlmsg_put(skb, 0, c->seq, NLMSG_DONE, 0, 0);
    if (!nlh) {
        kfree_skb(skb);
        return -ENOBUFS;
    }

    nlh->nlmsg_len = NLMSG_ALIGN(nlh->nlmsg_len);
    nlh->nlmsg_type = c->proto;
    netlink_broadcast(NETLINK_KOBJECT_UEVENT, skb, 0, 0, GFP_KERNEL);

    return 0;
}
